tool_input.script:
export const meta = {
  name: 'hook-experiment',
  description: 'Run two agents in parallel: one writes a.txt, one runs a 40-second sleep command',
  phases: [{ title: 'Run' }]
}

const results = await parallel([
  () => agent('Use the Write tool to create a file named a.txt containing the word alpha. Then reply done.', { label: 'write-a', phase: 'Run' }),
  () => agent('Run the shell command: node -e "setTimeout(()=>{},40000)" . Then reply done.', { label: 'sleep-40s', phase: 'Run' })
])

return results
